const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---- drawing helpers (PE_ prefix keeps them clear of engine globals) ---- */
const PE_F='font-family="Nunito Sans, sans-serif"';
const PE_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${PE_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const PE_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const PE_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex||''}/>`;
const PE_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return PE_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const PE_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(([x,y])=>x.toFixed(1)+','+y.toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const PE_badge=(x,y,n)=>`<circle cx="${x}" cy="${y}" r="17" fill="${TRED}" fill-opacity="${TOP}"/>`+PE_T(x,y+8,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
/* a PV module I-V shape (normalised: Isc = 1, Voc = 1); P = V × I, the MPP found by scanning */
const PE_Ipv=v=>Math.max(0,1-Math.exp((v-1)/0.08));
const PE_MPP=(()=>{let b=[0,0];for(let i=0;i<=1000;i++){const v=i/1000,p=v*PE_Ipv(v);if(p>b[1])b=[v,p]}return b})();
/* perturb and observe on that curve: start at 0.55 Voc, step 0.06, reverse whenever P falls */
const PE_PO=(()=>{let v=0.55,d=0.06,p=v*PE_Ipv(v);const out=[[v,p]];for(let k=0;k<7;k++){const v2=v+d,p2=v2*PE_Ipv(v2);if(p2<p)d=-d;v=v2;p=p2;out.push([v,p])}return out})();
/* hysteresis current control, simulated over one 50 Hz cycle: Vdc 400 V, grid peak 325 V, L 40 mH, peak reference 10 A, band 4 A (exaggerated to be visible) */
const PE_HY=(()=>{const Vdc=400,Vm=325,L=0.04,Im=10,h=4,w=2*Math.PI*50,dt=2e-6,N=10000;let i=0,s=1;const pts=[[0,0]];let sw=0;
 for(let k=1;k<=N;k++){const t=k*dt,vg=Vm*Math.sin(w*t),ir=Im*Math.sin(w*t);i+=(s*Vdc-vg)/L*dt;
  if(s>0&&i>ir+h/2){s=-1;pts.push([t,i]);sw++}else if(s<0&&i<ir-h/2){s=1;pts.push([t,i]);sw++}else if(k%50===0)pts.push([t,i])}
 return {pts,sw,T:N*dt,Im,h}})();
/* the chopped and burst heater waveforms */
const PE_chop=(x0,w,yc,A,al,cyc,col)=>{const P=[];const n=240*cyc;for(let k=0;k<=n;k++){const th=k/n*cyc*2*Math.PI,on=(th%Math.PI)>=al-1e-9;P.push([x0+k/n*w,yc-(on?A*Math.sin(th):0)])}return PE_poly(P,col,3)};
const PE_sine=(x0,w,yc,A,cyc,col,ex='')=>{const P=[];const n=120*cyc;for(let k=0;k<=n;k++){const th=k/n*cyc*2*Math.PI;P.push([x0+k/n*w,yc-A*Math.sin(th)])}return PE_poly(P,col,2,ex)};
const PE_burst=(x0,w,yc,A,on,tot,col)=>{const P=[],n=24*tot;for(let k=0;k<=n;k++){const th=k/n*tot*2*Math.PI,c=Math.floor(k/24);P.push([x0+k/n*w,yc-(c<on||k===n&&on===tot?A*Math.sin(th):0)])}return PE_poly(P,col,2.5)};
/* the battery bars of the first trap: 4444.4 Wh × 2 days ÷ 48 V, then ÷ 0.6 DoD, then ÷ 0.9 round trip */
const PE_AH=[4444.4*2/48, 4444.4*2/48/0.6, 4444.4*2/48/0.6/0.9];   // 185.2, 308.6, 342.9 Ah
